package com.rikkeibank.transaction.model; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="bank_transactions") public class BankTransaction{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true) private String operationId;@Column(nullable=false) private Long sourceAccountId;@Column(nullable=false) private Long targetAccountId;@Column(nullable=false,precision=19,scale=2) private BigDecimal amount;@Column(nullable=false) private String initiatorUsername;private String assignedTellerUsername;@Enumerated(EnumType.STRING) @Column(nullable=false) private TransactionStatus status;private String failureReason;private boolean reviewed;@Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();private LocalDateTime completedAt;public Long getId(){return id;}public String getOperationId(){return operationId;}public void setOperationId(String v){operationId=v;}public Long getSourceAccountId(){return sourceAccountId;}public void setSourceAccountId(Long v){sourceAccountId=v;}public Long getTargetAccountId(){return targetAccountId;}public void setTargetAccountId(Long v){targetAccountId=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public String getInitiatorUsername(){return initiatorUsername;}public void setInitiatorUsername(String v){initiatorUsername=v;}public String getAssignedTellerUsername(){return assignedTellerUsername;}public void setAssignedTellerUsername(String v){assignedTellerUsername=v;}public TransactionStatus getStatus(){return status;}public void setStatus(TransactionStatus v){status=v;}public String getFailureReason(){return failureReason;}public void setFailureReason(String v){failureReason=v;}public boolean isReviewed(){return reviewed;}public void setReviewed(boolean v){reviewed=v;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getCompletedAt(){return completedAt;}public void setCompletedAt(LocalDateTime v){completedAt=v;}}
